protected SysDaQueryExpression getInventDimFieldsToQueryObjectWhereClause()
{
    SysDaQueryExpression inventDimQueryExpression = next getInventDimFieldsToQueryObjectWhereClause();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        inventDimQueryExpression = new SysDaEqualsExpression(
            new SysDaFieldExpression(tradeAgreement, fieldStr(PriceDiscTable, InventDimId)),
            new SysDaFieldExpression(inventDim, fieldStr(InventDim, InventDimId)));
    }

    return inventDimQueryExpression;
}
